#!/usr/bin/env bash
# Compile the CPCV attestation circuit, run a local Groth16 trusted setup
# (Powers of Tau 2^15, no download), and export the verification key in both
# snarkjs and Soroban formats (§8.5).
#
# Outputs (committed):
#   apps/web/zk/cpcv_attestation.wasm
#   apps/web/zk/cpcv_attestation_final.zkey
#   apps/web/zk/verification_key.json
#   apps/web/zk/verification_key.soroban.json
#   apps/web/public/zk/verification_key.json  (served to the browser verifier)
#   contracts/cpcv_note/src/test_fixture.rs   (generated by test/make-fixture.mjs)
set -euo pipefail
cd "$(dirname "$0")"

ROOT="$(cd .. && pwd)"
BUILD=build
PTAU=ptau
OUT="$ROOT/apps/web/zk"
SNARKJS="node node_modules/snarkjs/build/cli.cjs"

mkdir -p "$BUILD" "$PTAU" "$OUT" "$ROOT/apps/web/public/zk"

echo "==> circom compile"
circom cpcv_attestation.circom --r1cs --wasm --sym -l node_modules -o "$BUILD"

entropy() { head -c 64 /dev/urandom | xxd -p | tr -d '\n'; }

if [ ! -f "$PTAU/pot15_final.ptau" ]; then
  echo "==> powers of tau (2^15, local)"
  $SNARKJS powersoftau new bn128 15 "$PTAU/pot15_0000.ptau"
  $SNARKJS powersoftau contribute "$PTAU/pot15_0000.ptau" "$PTAU/pot15_0001.ptau" \
    --name="explorador advance local ceremony" -e="$(entropy)"
  $SNARKJS powersoftau prepare phase2 "$PTAU/pot15_0001.ptau" "$PTAU/pot15_final.ptau"
fi

echo "==> groth16 setup"
$SNARKJS groth16 setup "$BUILD/cpcv_attestation.r1cs" "$PTAU/pot15_final.ptau" "$BUILD/cpcv_0000.zkey"
$SNARKJS zkey contribute "$BUILD/cpcv_0000.zkey" "$BUILD/cpcv_attestation_final.zkey" \
  --name="explorador advance phase 2" -e="$(entropy)"
$SNARKJS zkey export verificationkey "$BUILD/cpcv_attestation_final.zkey" "$BUILD/verification_key.json"

cp "$BUILD/cpcv_attestation_js/cpcv_attestation.wasm" "$OUT/cpcv_attestation.wasm"
cp "$BUILD/cpcv_attestation_final.zkey" "$OUT/cpcv_attestation_final.zkey"
cp "$BUILD/verification_key.json" "$OUT/verification_key.json"
cp "$BUILD/verification_key.json" "$ROOT/apps/web/public/zk/verification_key.json"

echo "==> Soroban-formatted verification key"
"$ROOT/node_modules/.bin/tsx" "$ROOT/scripts/vk-to-soroban.ts" "$OUT/verification_key.json" "$OUT/verification_key.soroban.json"

echo "==> fixture proof for the Rust tests"
"$ROOT/node_modules/.bin/tsx" test/make-fixture.ts

echo "Done."
